<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
if(getenv('ODONTOCARE_VALIDACAO_ISOLADA')!=='1'){fwrite(STDERR,"Exige ambiente isolado.\n");exit(2);}
foreach(['ODONTOCARE_API_URL','ODONTOCARE_DB_HOST','ODONTOCARE_DB_NAME','ODONTOCARE_DB_USER','ODONTOCARE_DB_PASS'] as $key){if(getenv($key)===false){fwrite(STDERR,"Configure $key.\n");exit(2);}}
require __DIR__.'/../OdontoCare-main/api/ApiClient.php';
$db=new PDO('mysql:host='.getenv('ODONTOCARE_DB_HOST').';dbname='.getenv('ODONTOCARE_DB_NAME').';charset=utf8mb4',getenv('ODONTOCARE_DB_USER'),getenv('ODONTOCARE_DB_PASS'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$results=[];
function note($name,$passed,$detail){global $results;$results[]=['test'=>$name,'passed'=>$passed,'detail'=>$detail];}
function insert($table,$data){global $db;$db->prepare('INSERT INTO '.$table.' ('.implode(',',array_keys($data)).') VALUES('.implode(',',array_fill(0,count($data),'?')).')')->execute(array_values($data));return (int)$db->lastInsertId();}
$login='race_'.bin2hex(random_bytes(5));$password=bin2hex(random_bytes(16));$salt=random_bytes(16);$hash='pbkdf2-sha256$210000$'.base64_encode($salt).'$'.base64_encode(hash_pbkdf2('sha256',$password,$salt,210000,32,true));
insert('usuario',['nome'=>'Teste concorrencia','login'=>$login,'senha'=>$hash,'tipoUsuario'=>'Administrador']);
$r=ApiClient::requisitar('POST','api/auth/login',['identificador'=>$login,'senha'=>$password]);if($r['status']!==200)throw new RuntimeException('Login de teste falhou.');session_start();$_SESSION['jwt']=$r['dados']['token'];
$dentists=[];$patients=[];for($i=0;$i<2;$i++){$dentists[]=insert('usuario',['nome'=>'Dentista sintetico','login'=>'race_'.bin2hex(random_bytes(5)),'senha'=>$hash,'tipoUsuario'=>'Dentista']);$patients[]=insert('paciente',['nome'=>'Paciente sintetico','cpf'=>substr((string)hrtime(true),-11)]);}
$procedure=insert('procedimento',['nomeProcedimento'=>'Procedimento concorrencia','valorProcedimento'=>'1.00']);
function payload($hour,$patient=0,$dentist=0){global $patients,$dentists,$procedure;return ['dataConsulta'=>'2027-04-15','horarioConsulta'=>$hour,'statusConsulta'=>'Agendada','idPaciente'=>$patients[$patient],'idUsuario'=>$dentists[$dentist],'idProcedimento'=>$procedure];}
function create($hour,$patient=0,$dentist=0){$r=ApiClient::requisitar('POST','api/consultas',payload($hour,$patient,$dentist));if($r['status']!==201)throw new RuntimeException('Preparação da consulta falhou.');return $r['dados']['idConsulta'];}
function parallel($requests){$multi=curl_multi_init();$handles=[];foreach($requests as [$method,$path,$body]){$h=curl_init(ApiClient::baseUrl().'/'.$path);curl_setopt_array($h,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$_SESSION['jwt']]]);if($body!==null)curl_setopt($h,CURLOPT_POSTFIELDS,json_encode($body));curl_multi_add_handle($multi,$h);$handles[]=$h;}do{curl_multi_exec($multi,$active);if($active)curl_multi_select($multi,1);}while($active);$codes=[];foreach($handles as $h){$codes[]=curl_getinfo($h,CURLINFO_HTTP_CODE);curl_multi_remove_handle($multi,$h);curl_close($h);}curl_multi_close($multi);return $codes;}
function countAt($hour){global $db,$dentists;$q=$db->prepare("SELECT COUNT(*) FROM consulta WHERE idUsuario IN (?,?) AND dataConsulta='2027-04-15' AND horarioConsulta=? AND statusConsulta<>'Cancelada'");$q->execute([$dentists[0],$dentists[1],$hour]);return (int)$q->fetchColumn();}
$codes=parallel([['POST','api/consultas',payload('09:00:00')],['POST','api/consultas',payload('09:00:00',1,0)]]);sort($codes);note('Mesmo profissional, pacientes diferentes',$codes===[201,409] && countAt('09:00:00')===1,$codes);
$codes=parallel([['POST','api/consultas',payload('10:00:00')],['POST','api/consultas',payload('10:00:00',0,1)]]);sort($codes);note('Mesmo paciente, profissionais diferentes',$codes===[201,409] && countAt('10:00:00')===1,$codes);
$a=create('11:00:00');$b=create('12:00:00',1);
$codes=parallel([['PUT',"api/consultas/$a",payload('13:00:00')],['PUT',"api/consultas/$b",payload('13:00:00',1)]]);sort($codes);note('Duas edicoes disputam horario',$codes===[200,409] && countAt('13:00:00')===1,$codes);
$c=create('14:00:00');$codes=parallel([['PUT',"api/consultas/$c",payload('15:00:00')],['POST','api/consultas',payload('15:00:00',1)]]);sort($codes);note('Criacao disputa horario com edicao',($codes===[200,409]||$codes===[201,409]) && countAt('15:00:00')===1,$codes);
$d=create('16:00:00');$codes=parallel([['PATCH',"api/consultas/$d/cancelar",null],['POST','api/consultas',payload('16:00:00',1)]]);sort($codes);$old=ApiClient::requisitar('GET',"api/consultas/$d");note('Cancelamento simultaneo a nova reserva',($codes===[200,201]||$codes===[200,409]) && countAt('16:00:00')<=1 && $old['dados']['statusConsulta']==='Cancelada',$codes);
$codes=parallel([['POST','api/consultas',payload('17:00:00')],['POST','api/consultas',payload('17:00:00',1,1)]]);sort($codes);note('Recursos distintos aceitam mesmo horario',$codes===[201,201] && countAt('17:00:00')===2,$codes);
$output=['database'=>$db->query('SELECT VERSION()')->fetchColumn(),'results'=>$results];if(getenv('ODONTOCARE_VALIDACAO_RESULTADO'))file_put_contents(getenv('ODONTOCARE_VALIDACAO_RESULTADO'),json_encode($output,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));foreach($results as $r)echo ($r['passed']?'PASS ':'FAIL ').$r['test'].' '.json_encode($r['detail']).PHP_EOL;exit(count(array_filter($results,fn($r)=>!$r['passed']))?1:0);
